'use strict';
// Inspection fixtures are scoped to History; live integration must query the same owned IDs as List.
const historyExamples=[
 {id:'history-figma',name:'Figma',price:'59.99',currency:'USD',cycle:'Monthly',category:'Productivity',status:'Cancelled',cancelledAt:'2026-10-25',accessUntil:'2026-11-01',renewal:'2026-11-01',estimated:false,source:'Manual'},
 {id:'history-netflix',name:'Netflix',price:'13.99',currency:'USD',cycle:'Monthly',category:'Entertainment',status:'Expired',expiredAt:'2026-10-20',expirySource:'user-confirmed',renewal:'',estimated:false,source:'Manual'},
 {id:'history-notion',name:'Notion',price:'17.00',currency:'USD',cycle:'Monthly',category:'Productivity',status:'Expired',expiredAt:'2026-10-12',expirySource:'email-confirmed',renewal:'',estimated:false,source:'Gmail',inboxEmail:'alex@example.com'}
];
const historyView={query:'',statuses:new Set()};
let historyTrigger=null;
function historyDate(r){return (r.status==='Cancelled'?r.cancelledAt:r.expiredAt)||'';}
function historyEligible(r){return r.status==='Cancelled'||(r.status==='Expired'&&!!r.expiredAt&&['user-confirmed','email-confirmed','confirmed-access-end'].includes(r.expirySource));}
function matchesHistory(r,view){return historyEligible(r)&&r.name.toLowerCase().includes(view.query.trim().toLowerCase())&&(!view.statuses.size||view.statuses.has(r.status));}
function historyData(){if(current==='History · empty')return [];const map=new Map(historyExamples.map(r=>[r.id,r]));for(const r of subscriptionListData())map.set(r.id,r);for(const [id,r]of trialRecords)map.set(id,r);return [...map.values()].filter(historyEligible);}
function historyFilterCount(){return historyView.statuses.size;}
function historyEmpty(filtered){return `<div class="history-empty">${mascotView({expression:filtered?'sad':'neutral',size:108})}<h3>${filtered?'No matches found':'Nothing here yet'}</h3><p>${filtered?'Try another name or clear your filters.':'Your cancelled and expired subscriptions will appear here.'}</p><button class="history-empty-action" ${filtered?'data-history-clear':'data-go="List"'}>${filtered?'Clear search & filters':'View subscriptions'} <span aria-hidden="true">›</span></button></div>`;}
function historyCard(r){const cancelled=r.status==='Cancelled',date=historyDate(r);return subscriptionCard(r,{status:{key:cancelled?'cancelled':'expired',label:r.status+(date?' · '+detailDate(date):'')},timing:cancelled&&r.accessUntil?'Access until '+detailDate(r.accessUntil):'',caption:'Last price · '+r.cycle,estimated:false,attributes:`data-history-record="${escape(r.id)}" aria-label="${escape(r.name)} ${r.status.toLowerCase()} details"`});}
function historyResults(){const data=historyData(),items=data.filter(r=>matchesHistory(r,historyView,calendarToday)).sort((a,b)=>historyDate(b).localeCompare(historyDate(a))||a.id.localeCompare(b.id));return `<p class="history-count" role="status">${items.length} subscription${items.length===1?'':'s'}<span>Most recent first</span></p>${items.length?`<div class="rows subscription-rows history-rows">${items.map(historyCard).join('')}</div><p class="history-price-note">Last tracked prices, not confirmed payments.</p>`:historyEmpty(data.length>0)}`;}
function historyScreen(){return `<section class="history-screen"><div class="head">${btn('‹','Profile','back')}<h2>History</h2></div><p class="history-intro">Your cancelled and expired subscriptions.</p><label class="history-search">Search<input data-history-search type="search" placeholder="Search history" value="${escape(historyView.query)}"></label><div class="history-tools"><button class="list-filter-trigger" data-history-filters aria-haspopup="dialog" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M7 12h10M10 18h4"/></svg>Status filters${historyFilterCount()?`<span class="filter-badge">${historyFilterCount()}</span>`:''}</button></div><div class="history-results">${historyResults()}</div></section>`;}
function refreshHistory(){document.querySelectorAll('.history-results').forEach(el=>el.innerHTML=historyResults());const t=document.querySelector('[data-history-filters]');if(t)t.innerHTML=`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 6h16M7 12h10M10 18h4"/></svg>Status filters${historyFilterCount()?`<span class="filter-badge">${historyFilterCount()}</span>`:''}`;}
function closeHistoryFilters(){const overlay=document.querySelector('.history-filter-overlay');if(!overlay)return;const phone=overlay.closest('.phone');overlay.remove();phone.querySelectorAll('[data-history-inert]').forEach(el=>{el.inert=false;el.removeAttribute('data-history-inert');});historyTrigger?.setAttribute('aria-expanded','false');historyTrigger?.removeAttribute('aria-controls');historyTrigger?.focus();}
function refreshHistoryFilters(){refreshHistory();const overlay=document.querySelector('.history-filter-overlay');if(!overlay)return;overlay.querySelectorAll('[data-history-status]').forEach(input=>input.checked=input.dataset.historyStatus==='All'?!historyView.statuses.size:historyView.statuses.has(input.dataset.historyStatus));const count=historyData().filter(r=>matchesHistory(r,historyView)).length;overlay.querySelector('.filter-result-summary').textContent=count+' matching subscription'+(count===1?'':'s');}
function openHistoryFilters(trigger){historyTrigger=trigger;const phone=trigger.closest('.phone'),overlay=document.createElement('div'),data=historyData();overlay.className='history-filter-overlay';overlay.innerHTML=`<div class="history-filter-shade" data-history-close></div><section class="status-filter-dialog" role="dialog" aria-modal="true" aria-label="Filter history by status" id="history-status-dialog"><header><div><h3>Filter by status</h3><p>Choose one or more</p></div><button data-history-close aria-label="Close history filters">×</button></header><div class="status-filter-options">${['All','Cancelled','Expired'].map(status=>`<label class="status-filter-option"><input type="checkbox" data-history-status="${status}"><span class="${status==='All'?'':'status-'+status.toLowerCase()}">${status}</span><small>${status==='All'?data.length:data.filter(r=>r.status===status).length}</small></label>`).join('')}</div><footer><span class="filter-result-summary" role="status"></span><button class="filter-done" data-history-close>Done</button></footer></section>`;for(const el of phone.children){if(!el.inert){el.inert=true;el.dataset.historyInert='true';}}phone.append(overlay);trigger.setAttribute('aria-expanded','true');trigger.setAttribute('aria-controls','history-status-dialog');refreshHistoryFilters();overlay.querySelector('[data-history-close]').focus();}
document.addEventListener('input',e=>{if(e.target.matches('[data-history-search]')){historyView.query=e.target.value;refreshHistory();}});
document.addEventListener('change',e=>{if(!e.target.matches('[data-history-status]'))return;const status=e.target.dataset.historyStatus;if(status==='All')historyView.statuses.clear();else if(e.target.checked)historyView.statuses.add(status);else historyView.statuses.delete(status);refreshHistoryFilters();});
document.addEventListener('click',e=>{const open=e.target.closest('[data-history-filters]'),close=e.target.closest('[data-history-close]'),clear=e.target.closest('[data-history-clear]'),row=e.target.closest('[data-history-record]');if(open)openHistoryFilters(open);else if(close)closeHistoryFilters();else if(clear){historyView.query='';historyView.statuses.clear();const search=document.querySelector('[data-history-search]');if(search)search.value='';refreshHistory();}else if(row){const r=historyData().find(r=>r.id===row.dataset.historyRecord);if(!r)return;state.manual={...r};demoName=r.name;demoPrice=r.price;go('Detail');}});
document.addEventListener('keydown',e=>{const overlay=document.querySelector('.history-filter-overlay');if(!overlay)return;if(e.key==='Escape'){e.preventDefault();closeHistoryFilters();}else if(e.key==='Tab'){const controls=[...overlay.querySelectorAll('button:not([disabled]),input:not([type=hidden])')].filter(el=>el.getClientRects().length),first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
